import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { BrowserRouter as Router, Routes, Route, Link, useNavigate } from 'react-router-dom';

// --- COMPONENTS ---

const Navbar = ({ cartCount }) => (
  <nav className="bg-white/95 backdrop-blur-md shadow-sm sticky top-0 z-50 w-full border-b border-gray-100">
    <div className="w-full px-6 md:px-12"> 
      <div className="flex justify-between items-center h-20">

        {/* LOGO JIDID: Couverts 🍴 */}
        <Link to="/" className="flex items-center space-x-4 group">
          <div className="relative">
            {/* Kandirou l-icon f wast dayra orange bach t-ji professional */}
            <div className="bg-orange-600 p-2 rounded-full shadow-lg transform group-hover:rotate-12 transition duration-300">
                <svg width="28" height="28" viewBox="0 0 512 512" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M416 0C380.7 0 352 28.7 352 64V288c0 17.7 14.3 32 32 32h32V480c0 17.7 14.3 32 32 32s32-14.3 32-32V32C480 14.3 465.7 0 448 0H416zM80 0C44.7 0 16 28.7 16 64V224c0 35.3 28.7 64 64 64h16V480c0 17.7 14.3 32 32 32s32-14.3 32-32V288h16c35.3 0 64-28.7 64-64V64c0-35.3-28.7-64-64-64H80zM128 0V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H80V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H16V192c0 53 43 96 96 96v192c0 17.7 14.3 32 32 32s32-14.3 32-32V288c53 0 96-43 96-96V0H224V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H160V192c0 8.8-7.2 16-16 16s-16-7.2-16-16V0H128z" fill="white"/>
                </svg>
            </div>
          </div>
          <div className="flex flex-col text-left border-l-2 border-gray-100 pl-4">
            <span className="font-black text-2xl text-gray-900 leading-none tracking-tighter uppercase italic">
              FAST<span className="text-orange-600">DÉLICE</span>
            </span>
            <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">Cuisine de Chef</span>
          </div>
        </Link>

        {/* Links */}
        <div className="hidden lg:flex items-center space-x-10 font-black text-gray-600 uppercase text-[11px] tracking-widest">
          <Link to="/" className="hover:text-orange-600 transition">Accueil</Link>
          <Link to="/menu" className="hover:text-orange-600 transition">Menu</Link>
          <Link to="/about" className="hover:text-orange-600 transition">À Propos</Link>
        </div>

        {/* Cart & Login */}
        <div className="flex items-center space-x-6">
          <Link to="/panier" className="relative flex items-center bg-gray-50 px-4 py-2 rounded-xl text-gray-800 hover:bg-orange-50 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
            </svg>
            <span className="font-black text-xs uppercase tracking-widest">Panier</span>
            <span className="ml-2 bg-orange-600 text-white text-[10px] font-bold rounded-md px-1.5 py-0.5">{cartCount}</span>
          </Link>
          <Link to="/login" className="bg-gray-900 text-white px-6 py-3 rounded-xl hover:bg-orange-600 transition duration-300 font-black text-xs uppercase tracking-widest shadow-md">Connexion</Link>
        </div>
      </div>
    </div>
  </nav>
);

// Page Layout with Fixed Premium Background
const PageLayout = ({ children, title }) => (
  <div className="relative min-h-screen w-full flex flex-col items-center">
    <div className="fixed inset-0 z-0">
      <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="bg" />
      <div className="absolute inset-0 bg-black/75 backdrop-blur-[2px]"></div>
    </div>
    <div className="relative z-10 w-full max-w-7xl px-6 py-20">
      {title && (
        <div className="text-center mb-16">
          <h2 className="text-6xl md:text-8xl font-black text-white italic tracking-tighter drop-shadow-2xl uppercase">{title}</h2>
          <div className="h-2 w-24 bg-orange-600 mx-auto mt-4 rounded-full"></div>
        </div>
      )}
      {children}
    </div>
  </div>
);

// --- PAGES ---

const Home = () => (
  <PageLayout>
    <div className="text-center py-20 flex flex-col items-center">
      <div className="bg-white/10 backdrop-blur-md px-8 py-2 rounded-full border border-white/20 text-orange-500 font-black text-xs uppercase tracking-[0.4em] mb-8 animate-bounce">Best in Town</div>
      <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">Fast<span className="text-orange-500">Délice</span></h1>
      <p className="text-xl md:text-2xl mb-12 font-medium text-gray-300 italic max-w-2xl mx-auto">L'art de la cuisine rapide et raffinée, où chaque bouchée raconte une histoire.</p>
      <Link to="/menu" className="bg-orange-600 hover:bg-white hover:text-orange-600 text-white px-16 py-6 rounded-2xl text-xl font-black transition-all duration-300 shadow-2xl uppercase tracking-widest transform hover:scale-105 active:scale-95">Découvrir le Menu</Link>
    </div>
  </PageLayout>
);

const About = () => (
    <PageLayout title="À Propos">
      <div className="max-w-4xl mx-auto bg-white/10 backdrop-blur-xl border border-white/20 p-12 rounded-[3.5rem] text-white shadow-2xl relative overflow-hidden">
        <div className="absolute -top-24 -right-24 w-64 h-64 bg-orange-600/20 rounded-full blur-3xl"></div>
        <h3 className="text-3xl font-black mb-8 text-orange-500 italic uppercase tracking-tight">Notre Philosophie</h3>
        <p className="text-xl leading-relaxed text-gray-200 mb-10 font-medium italic">
          FastDélice n'est pas seulement un restaurant, c'est une destination culinaire. Nous marions la précision du service avec la générosité des saveurs méditerranéennes.
        </p>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
          {[
            { t: "Qualité", d: "Produits frais et locaux, travaillés avec respect par nos chefs." },
            { t: "Passion", d: "Chaque plat est une création unique pour ravir vos sens." }
          ].map((item, i) => (
            <div key={i} className="bg-black/20 p-8 rounded-3xl border border-white/5 hover:border-orange-500/50 transition">
              <h4 className="text-orange-500 font-black uppercase text-xs mb-3 tracking-[0.2em]">{item.t}</h4>
              <p className="text-sm text-gray-400 font-bold">{item.d}</p>
            </div>
          ))}
        </div>
      </div>
    </PageLayout>
);

const Menu = ({ categories, addToCart }) => {
    const [searchTerm, setSearchTerm] = useState("");
    const [selectedDish, setSelectedDish] = useState(null);
    const navigate = useNavigate();

    const filteredItems = categories.flatMap(cat => 
      cat.dishes.map(dish => ({ ...dish, categoryName: cat.name }))
    ).filter(item => item.name.toLowerCase().includes(searchTerm.toLowerCase()));

    const confirmOrder = (type) => {
      addToCart({ ...selectedDish, orderType: type });
      setSelectedDish(null);
      navigate('/panier');
    };

    return (
      <PageLayout title="Menu">
        <div className="max-w-xl mx-auto mb-16 relative">
          <input type="text" placeholder="Qu'allez-vous déguster ?" className="w-full px-16 py-6 rounded-3xl bg-white/10 backdrop-blur-md border border-white/20 outline-none focus:ring-4 focus:ring-orange-500/50 font-bold text-white placeholder-gray-400 transition text-lg" onChange={(e) => setSearchTerm(e.target.value)} />
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 absolute left-6 top-1/2 -translate-y-1/2 text-orange-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
          {filteredItems.map(item => (
            <div key={item.id} className="group bg-white/10 backdrop-blur-xl border border-white/10 rounded-[3rem] overflow-hidden hover:scale-105 transition duration-500 shadow-2xl relative">
              <div className="h-64 bg-black/40 flex items-center justify-center text-8xl transform group-hover:scale-110 transition duration-500">
                {item.categoryName.toLowerCase().includes('pizza') ? '🍕' : '🌮'}
              </div>
              <div className="p-10 text-center">
                <span className="text-[10px] font-black uppercase text-orange-500 tracking-[0.3em] block mb-2">{item.categoryName}</span>
                <h3 className="text-2xl font-black text-white mb-6 italic">{item.name}</h3>
                <div className="flex items-center justify-between mt-4">
                    <span className="text-2xl font-black text-white">{item.price} <span className="text-orange-500 text-sm italic">DH</span></span>
                    <button onClick={() => setSelectedDish(item)} className="bg-orange-600 text-white px-8 py-3 rounded-2xl font-black text-xs uppercase hover:bg-white hover:text-black transition shadow-lg tracking-widest">Commander</button>
                </div>
              </div>
            </div>
          ))}
        </div>

        {selectedDish && (
          <div className="fixed inset-0 bg-black/90 backdrop-blur-xl z-[100] flex items-center justify-center p-6">
            <div className="bg-white rounded-[4rem] p-16 max-w-md w-full shadow-2xl text-center relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-2 bg-orange-600"></div>
              <h3 className="text-4xl font-black text-gray-900 mb-4 italic">Dégustation</h3>
              <p className="text-gray-500 mb-10 font-bold uppercase text-xs tracking-widest">Pour votre {selectedDish.name}</p>
              <div className="space-y-4">
                <button onClick={() => confirmOrder('Sur Place')} className="w-full py-6 bg-orange-600 text-white rounded-2xl font-black text-lg hover:bg-orange-700 transition shadow-xl transform active:scale-95">🍽️ Sur Place</button>
                <button onClick={() => confirmOrder('Emporter')} className="w-full py-6 bg-gray-900 text-white rounded-2xl font-black text-lg hover:bg-black transition shadow-xl transform active:scale-95">🥡 À Emporter</button>
                <button onClick={() => setSelectedDish(null)} className="w-full py-4 text-gray-400 font-bold text-xs uppercase mt-6">Annuler</button>
              </div>
            </div>
          </div>
        )}
      </PageLayout>
    );
};

const PanierPage = ({ cart }) => (
    <PageLayout title="Panier">
      {cart.length === 0 ? (
        <div className="text-center py-20 text-white/10 font-black text-6xl italic tracking-tighter">Votre table est vide...</div>
      ) : (
        <div className="bg-white/10 backdrop-blur-xl border border-white/10 p-12 rounded-[4rem] shadow-2xl max-w-2xl mx-auto text-white">
          {cart.map((item, index) => (
            <div key={index} className="flex justify-between items-center py-8 border-b border-white/5 last:border-0">
              <div>
                <h3 className="text-2xl font-black italic mb-1">{item.name}</h3>
                <span className="text-orange-500 text-[10px] font-black uppercase tracking-[0.3em]">{item.orderType}</span>
              </div>
              <span className="text-2xl font-black text-white">{item.price} DH</span>
            </div>
          ))}
          <div className="mt-12 pt-12 border-t-2 border-orange-600 flex justify-between items-center">
            <span className="text-3xl font-black italic tracking-tighter">TOTAL</span>
            <span className="text-5xl font-black text-orange-500 tracking-tighter">{cart.reduce((total, item) => total + parseFloat(item.price), 0).toFixed(2)} DH</span>
          </div>
          <button className="w-full mt-12 bg-white text-gray-900 py-7 rounded-3xl font-black text-xl hover:bg-orange-600 hover:text-white transition shadow-2xl uppercase tracking-widest transform hover:scale-105 transition duration-300">Confirmer la Commande</button>
        </div>
      )}
    </PageLayout>
);

// --- MAIN APP ---

// Redoubtable export bach n-7ellou l-mochkil dyal (module has no exports)
export default function App() {
  const [categories, setCategories] = useState([]);
  const [cart, setCart] = useState([]);

  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/categories/')
      .then(res => setCategories(res.data))
      .catch(err => console.error(err));
  }, []);

  const addToCart = (item) => setCart([...cart, item]);

  return (
    <Router>
      <div className="min-h-screen bg-black overflow-x-hidden selection:bg-orange-600 selection:text-white">
        <Navbar cartCount={cart.length} />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/menu" element={<Menu categories={categories} addToCart={addToCart} />} />
          <Route path="/about" element={<About />} />
          <Route path="/panier" element={<PanierPage cart={cart} />} />
          <Route path="/login" element={<PageLayout title="Login"><div className="h-40"></div></PageLayout>} />
        </Routes>
        <footer className="relative z-10 bg-black py-20 text-center text-gray-700 font-bold uppercase tracking-[0.5em] text-[9px] border-t border-white/5">
          © 2026 FAST DÉLICE. Excellence & Saveur.
        </footer>
      </div>
    </Router>
  );
}
